Here's a Python program that meets your requirements. It handles invalid inputs and divisions by zero.

```python
def get_valid_input(prompt):
    while True:
        try:
            user_input = float(input(prompt))
            return user_input
        except ValueError:
            print("Invalid input. Please enter a number.")

def perform_operation(num1, num2, operation):
    if operation == '+':
        return num1 + num2
    elif operation == '-':
        return num1 - num2
    elif operation == '*':
        return num1 * num2
    elif operation == '/':
        if num2 == 0:
            print("Division by zero is not allowed.")
            return None
        else:
            return num1 / num2
    else:
        print("Invalid operation. Please enter '+' for addition, '-' for subtraction, '*' for multiplication, or '/' for division.")
        return None

def main():
    num1 = get_valid_input("Enter the first number: ")
    num2 = get_valid_input("Enter the second number: ")
    operation = input("Enter the operation (+, -, *, /): ")

    result = perform_operation(num1, num2, operation)

    if result is not None:
        print(f"{num1} {operation} {num2} = {result}")

if __name__ == "__main__":
    main()
```

This program will prompt the user to enter three numbers and an operation. It will then perform the operation and display the result. If the user enters an invalid operation or division by zero, the program will inform the user and prompt for a new input.
